      ro: ["Strada se întinde pe o lungime de aproximativ 300 de metri.", "A fost numită în anii 1920 după poetul abbasid Al-Mutanabbi.", "La 5 martie 2007, o mașină-capcană a distrus mari părți ale străzii și a ucis 30 de persoane.", "Redeschiderea oficială după atac a avut loc la 18 decembrie 2008.", "Cafeneaua Shabandar de la capătul străzii și-a început activitatea în anul 1917.", "Pe malul Tigrului se află o statuie din bronz a lui Al-Mutanabbi, creată de sculptorul Mohammed Ghani Hikmat.", "Astăzi, peste 100 de librării și edituri sunt stabilite pe această stradă."],
      en: ["The street was named after the famous 10th-century Arab poet Al-Mutanabbi.", "The historic Shahbandar Cafe opened its doors to intellectuals in 1932.", "A car bomb attack on March 5, 2007, killed 30 people in the book market.", "The fully restored book market was officially reopened to the public in December 2008.", "The Al-Qishla clock tower at the end of the street was constructed in 1869.", "A bronze statue of Al-Mutanabbi was erected along the Tigris River in 1968."],
      es: ["La calle tiene una longitud de unos 300 metros.", "Se le dio el nombre del poeta abasí Al-Mutanabbi en la década de 1920.", "El 5 de marzo de 2007, un coche bomba destruyó gran parte de la calle y mató a 30 personas.", "La reapertura oficial tras el atentado tuvo lugar el 18 de diciembre de 2008.", "El café Shabandar, al final de la calle, comenzó a funcionar en 1917.", "A orillas del Tigris hay una estatua de bronce de Al-Mutanabbi, creada por el escultor Mohammed Ghani Hikmat.", "Más de 100 librerías y editoriales tienen hoy su sede en la calle."],
      pt: ["A rua estende-se por uma extensão de cerca de 300 metros.", "Foi batizada na década de 1920 em homenagem ao poeta abássida Al-Mutanabbi.", "Em 5 de março de 2007, um carro-bomba destruiu grande parte da rua e matou 30 pessoas.", "A reabertura oficial após o atentado ocorreu em 18 de dezembro de 2008.", "O Shabandar Café, no final da rua, iniciou as suas operações em 1917.", "Às margens do rio Tigre encontra-se uma estátua de bronze de Al-Mutanabbi, criada pelo escultor Mohammed Ghani Hikmat.", "Mais de 100 livrarias e editoras estão sediadas na rua hoje."],
      fr: ["La rue s'étend sur une longueur d'environ 300 mètres.", "Elle a été nommée d'après le poète abbasside Al-Mutanabbi dans les années 1920.", "Le 5 mars 2007, une voiture piégée a détruit une grande partie de la rue, tuant 30 personnes.", "La réouverture officielle après l'attentat a eu lieu le 18 décembre 2008.", "Le café Shabandar, au bout de la rue, a ouvert ses portes en 1917.", "Sur les rives du Tigre se dresse une statue en bronze d'Al-Mutanabbi, créée par le sculpteur Mohammed Ghani Hikmat.", "Plus de 100 librairies et maisons d'édition sont aujourd'hui installées dans la rue."],
