      es: "Un importante santuario islámico en Bagdad donde están enterrados el séptimo y el noveno imán chií.",
      pt: "Um importante santuário islâmico em Bagdá, onde estão sepultados o sétimo e o nono imames xiitas.",
      fr: "Un important sanctuaire islamique de Bagdad où sont enterrés les septième et neuvième imams chiites.",
