      ro: ["Aici se odihnesc al zecelea și al unsprezecelea dintre cei doisprezece imami șiiți.", "Faimoasa cupolă de aur a fost distrusă într-un bombardament din 2006 și ulterior reconstruită.", "Un simbol central al semnificației spirituale din Samarra."],
